    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b <= 32 && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            long val = 0;
            while (b > 32) {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return val;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) return;
        int k = scanner.nextInt();

        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextLong();
        }

        long[] b = new long[n];
        for (int i = 0; i < n; i++) {
            b[i] = scanner.nextLong();
        }

        long sumBase = 0;
        long[] g = new long[n];

        for (int i = 0; i < n; i++) {
            long diff = a[i] - b[i];
            if (diff > 0) {
                sumBase += diff;
            }
            g[i] = Math.min(a[i], b[i]);
        }

        Arrays.sort(g);

        int kPrime = Math.min(k, n - 1);
        int take = kPrime + 1;

        long sumG = 0;
        for (int i = 0; i < take; i++) {
            sumG += g[n - 1 - i];
        }

        long ans = sumBase + sumG;
        System.out.println(ans);
    }
}
